                            sb.AppendIndentedLine($"writer.WriteZigZag32({objectName}.{protoMember.Name});");
                            break;
                        default:
                            WritePrecomputedTag(sb, protoMember.FieldId, WireType.VarInt);
                            sb.AppendIndentedLine($"writer.WriteVarInt32({objectName}.{protoMember.Name});");
                            break;
                    }
                    sb.EndBlock();
